<script setup lang="ts">import {ref,computed} from 'vue';import {Check,ArrowLeft,ArrowRight,CreditCard,Gift,MapPin,Clock} from 'lucide-vue-next';import {money} from '../data';import {useShopStore} from '../stores/shop';const store=useShopStore();const step=ref(0);const done=ref(false);const form=ref({first:'',last:'',phone:'',governorate:'',area:'',block:'',street:'',building:'',date:'',slot:'',gift:false,message:'',payment:'card'});const delivery=computed(()=>store.cartTotal>=20?0:2);const total=computed(()=>store.cartTotal+delivery.value);function next(){if(step.value<3)step.value++;else{done.value=true;store.clear()}}</script><template><section class="section checkout-page"><div class="container"><div v-if="done" class="success-card"><div class="success-icon"><Check/></div><span class="eyebrow">Order Confirmed</span><h1>Thank you for your order!</h1><p>Your order number is <b>OB-24071</b>. We sent the details to your phone and email.</p><RouterLink class="btn primary" to="/order/OB-24071">Track Your Order</RouterLink></div><template v-else><div class="checkout-head"><span class="eyebrow">Secure Checkout</span><h1>Complete Your Order</h1></div><div class="steps"><span v-for="(s,i) in ['Delivery','Schedule','Gift','Payment']" :class="{active:i===step,done:i<step}"><b>{{i<step?'✓':i+1}}</b>{{s}}</span></div><div class="checkout-layout"><div class="checkout-form"><section v-if="step===0"><h2><MapPin/> Delivery Details</h2><div class="form-grid"><label>First name<input v-model="form.first" placeholder="First name"></label><label>Last name<input v-model="form.last" placeholder="Last name"></label><label class="span2">Phone<input v-model="form.phone" placeholder="+965 9XXX XXXX"></label><label>Governorate<select v-model="form.governorate"><option disabled value="">Choose governorate</option><option>Capital</option><option>Hawalli</option><option>Farwaniya</option><option>Mubarak Al-Kabeer</option><option>Ahmadi</option><option>Jahra</option></select></label><label>Area<input v-model="form.area"></label><label>Block<input v-model="form.block"></label><label>Street<input v-model="form.street"></label><label class="span2">Building / Apartment<input v-model="form.building"></label></div></section><section v-if="step===1"><h2><Clock/> Delivery Schedule</h2><h3>Select a date</h3><div class="choice-grid"><button v-for="d in ['Today','Tomorrow','Tuesday','Wednesday']" :class="{selected:form.date===d}" @click="form.date=d">{{d}}</button></div><h3>Select a time</h3><div class="choice-grid"><button v-for="t in ['10 AM – 1 PM','1 PM – 4 PM','4 PM – 7 PM','7 PM – 10 PM']" :class="{selected:form.slot===t}" @click="form.slot=t">{{t}}</button></div></section><section v-if="step===2"><h2><Gift/> Gift Options</h2><label class="toggle-card"><input type="checkbox" v-model="form.gift"><span><b>This is a gift</b><small>Add a complimentary message for someone special.</small></span></label><label v-if="form.gift">Gift message<textarea v-model="form.message" maxlength="200" placeholder="Write your message..."></textarea></label></section><section v-if="step===3"><h2><CreditCard/> Payment</h2><div class="payment-options"><label :class="{selected:form.payment==='card'}"><input type="radio" v-model="form.payment" value="card"><span><b>Credit / Debit Card</b><small>Visa, Mastercard and KNET</small></span></label><label :class="{selected:form.payment==='cash'}"><input type="radio" v-model="form.payment" value="cash"><span><b>Cash on Delivery</b><small>Pay when your order arrives</small></span></label></div><div v-if="form.payment==='card'" class="form-grid"><label class="span2">Card number<input placeholder="0000 0000 0000 0000"></label><label>Expiry<input placeholder="MM / YY"></label><label>CVV<input placeholder="123"></label></div></section><div class="checkout-actions"><button class="btn secondary" :disabled="step===0" @click="step--"><ArrowLeft :size="17"/> Back</button><button class="btn primary" @click="next">{{step===3?'Place Order':'Continue'}} <ArrowRight :size="17"/></button></div></div><aside class="summary"><h2>Your Order</h2><div v-for="item in store.cart" class="mini-order"><img :src="item.product.image"><span><b>{{item.product.name}}</b><small>Qty {{item.quantity}}</small></span><strong>{{money(item.product.price*item.quantity)}}</strong></div><div><span>Subtotal</span><b>{{money(store.cartTotal)}}</b></div><div><span>Delivery</span><b>{{delivery?money(delivery):'Free'}}</b></div><div class="total"><span>Total</span><b>{{money(total)}}</b></div></aside></div></template></div></section></template>
